/* MedicCare.module.css — faithful port of Medic Care (Templatemo) */

:root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;
}

.root {
  background: var(--vt-surface);
  font-family: 'Open Sans', sans-serif;
  position: relative;
  padding-top: 94px;
  color: var(--vt-ink);
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: inherit;
  font-weight: 600;
}

.root h1,
.root h2 {
  font-weight: 700;
}

.root h1 {
  font-size: 48px;
  line-height: normal;
}

.root h2 {
  font-size: 36px;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* ---------- Navigation ---------- */
.nav {
  background: var(--vt-surface-2);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1030;
  padding-top: 20px;
  padding-bottom: 20px;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  position: relative;
}

.logo {
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  margin: 0 30px;
  padding: 0;
  text-align: center;
  text-decoration: none;
  display: inline-block;
}

.logo:hover {
  color: var(--vt-accent);
}

.brand {
  display: block;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* ---------- Hero ---------- */
.hero {
  padding-top: 0;
}

.hero .container {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 100%;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
}

.heroTitle {
  margin-bottom: 0.5rem;
}

.heroWord {
  color: var(--vt-accent);
}

.heroSub {
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  box-sizing: border-box;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  margin: 0;
}

/* ---------- Utility ---------- */
:global(.text-center) {
  text-align: center;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

/* ---------- About ---------- */
.about {
  background: var(--vt-surface);
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
}

.aboutColText {
  flex: 1 1 50%;
}

.aboutColImage {
  flex: 1 1 40%;
}

.aboutImage {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 0.25rem;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
}

.sectionTitle {
  margin-bottom: 1.5rem;
}

/* ---------- Gallery ---------- */
.gallery {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1 1 50%;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ---------- Timeline ---------- */
.timelineSection {
  padding-bottom: 0;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNodes {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-around;
  margin-bottom: 2rem;
}

.timelineNodes.odd {
  flex-direction: row;
}

.timelineNodes.even {
  flex-direction: row-reverse;
}

.timelineContent {
  flex: 0 0 45%;
  position: relative;
  border-radius: 0 0 0.25rem 0.25rem;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  padding: 0;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  margin-bottom: 0;
}

.timelineText {
  padding: 10px 30px;
  margin-bottom: 0;
}

.timelineNodes.odd .timelineTitle,
.timelineNodes.odd .timelineText {
  text-align: right;
}

.timelineNodes.even .timelineTitle,
.timelineNodes.even .timelineText {
  text-align: left;
}

.timelineNodes.odd .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNodes.even .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIcons {
  position: relative;
  z-index: 2;
  flex: 0 0 80px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0 1rem;
}

.timelineIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  color: var(--vt-accent);
  font-size: 32px;
  line-height: 1;
}

.timelineDate {
  flex: 1;
  padding: 1rem;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.timelineNodes.odd .timelineDate {
  text-align: left;
}

.timelineNodes.even .timelineDate {
  text-align: right;
}

/* ---------- Footer ---------- */
.footer {
  background: var(--vt-surface-2);
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1 1 25%;
  min-width: 200px;
}

.footerTitle {
  margin-bottom: 1.5rem;
}

.hoursText {
  white-space: pre-line;
  line-height: 1.8;
}

.footerBottom {
  margin-top: 4rem;
  text-align: center;
}

.copyrightText {
  font-size: 16px;
}

/* ---------- Social (inherited from SocialLinks component) ---------- */
/* We assume SocialLinks renders ul with class social-icon, but to keep module pure we style via :global if needed */
:global(.social-icon) {
  list-style: none;
  padding: 0;
  margin: 0;
}

:global(.social-icon li) {
  display: inline-block;
  margin-right: 15px;
}

:global(.social-icon a) {
  font-size: 18px;
  color: var(--vt-ink-soft);
  transition: color 0.3s;
}

:global(.social-icon a:hover) {
  color: var(--vt-accent);
}

/* ---------- Responsive ---------- */
@media screen and (min-width: 1600px) {
  .hero .container {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 { font-size: 38px; }
  .root h2 { font-size: 32px; }
  .root h3 { font-size: 26px; }
  .root h4 { font-size: 24px; }
  .root h5 { font-size: 20px; }
  .root h6 { font-size: 18px; }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .hero .container {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .aboutRow {
    flex-direction: column;
  }

  .aboutColText,
  .aboutColImage {
    flex: 1 1 100%;
  }

  .timeline::before {
    left: 33px;
    transform: none;
    top: 60px;
    height: 90%;
  }

  .timelineNodes.odd,
  .timelineNodes.even {
    flex-direction: column;
    align-items: flex-start;
  }

  .timelineContent {
    flex: 0 0 auto;
    width: calc(100% - 60px);
    margin-left: 60px;
  }

  .timelineIcons {
    position: absolute;
    left: 0;
    top: 0;
    flex: none;
    margin: 0;
    width: 60px;
  }

  .timelineIcon {
    width: 60px;
    height: 60px;
    font-size: 24px;
  }

  .timelineNodes.odd .timelineTitle,
  .timelineNodes.odd .timelineText {
    text-align: left;
  }

  .timelineNodes.odd .timelineTitle::after,
  .timelineNodes.even .timelineTitle::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }

  .timelineDate {
    text-align: left;
    margin-left: 60px;
    width: calc(100% - 60px);
  }

  .footerRow {
    flex-direction: column;
  }

  .footerCol {
    flex: 1 1 100%;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .navIn {
    flex-wrap: wrap;
  }

  .navLinks {
    order: 3;
    width: 100%;
    justify-content: center;
    gap: 1rem;
  }

  .logo {
    margin: 0 1rem;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIcons {
    left: -10px;
  }

  .timelineIcon {
    width: 70px;
    height: 70px;
    font-size: 28px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIcon {
    width: 55px;
    height: 55px;
    font-size: 22px;
  }
}
